script:
frappe.ui.form.on('Minutes Of The Meeting', {
    onload: function(frm) {
        if (frm.is_new()) {
            // รับอีเมลของผู้ใช้ปัจจุบัน
            let user_email = frappe.session.user;

            // เรียกใช้ฟังก์ชันฝั่งเซิร์ฟเวอร์เพื่อรับข้อมูลผู้ใช้
            frappe.call({
                method: 'frappe.client.get',
                args: {
                    doctype: 'User',
                    name: user_email
                },
                callback: function(response) {
                    if (response.message) {
                        let user_doc = response.message;
                        // เข้าถึงฟิลด์ full_name
                        let full_name = user_doc.full_name;
                        
                        // ตั้งค่าในแบบฟอร์มกำหนดการทำงาน
                        frm.set_value('fullname', full_name);
                        
                        // รีเฟรชฟิลด์เพื่อให้แน่ใจว่ามีการอัปเดตแล้ว
                        frm.refresh_field('fullname');
                       
                    }
                }
            });
        }
    }
});

frappe.ui.form.on('Minutes Of The Meeting', {
    fullname: function(frm) {
        frappe.call({
            method: "frappe.client.get_value",
            args: { 
                doctype: "Personnel",
                fieldname: ["department"],
                filters: { name: frm.doc.fullname },
            },
            callback: function(r) {
                if (r.message) {
                    cur_frm.set_value("department", r.message.department);
                    frm.trigger('onload'); // เรียก onload ใหม่หลังจากดึงข้อมูล
                }
            }
        });
    }
});



frappe.ui.form.on("Minutes Of The Meeting", {
    meeting_participants: function(frm) {
        if (frm.doc.meeting_participants) {
            // ดึงข้อมูล Personnel ที่เลือก
            frappe.db.get_doc("Personnel", frm.doc.meeting_participants).then(personnel => {
                
                // ตรวจสอบว่าตาราง meeting_participants_table มีข้อมูลหรือยัง ถ้าไม่มีให้กำหนดเป็นอาร์เรย์ว่าง
                if (!frm.doc.meeting_participants_table) {
                    frm.doc.meeting_participants_table = [];
                }

                // ตรวจสอบว่ามี Personnel นี้อยู่ในตารางหรือยัง
                let exists = frm.doc.meeting_participants_table.some(row => row.list_meeting_participants === personnel.name);

                if (!exists) {
                    // เพิ่มแถวใหม่ใน Child Table
                    let new_row = frm.add_child("meeting_participants_table");
                    new_row.list_meeting_participants = personnel.name;

                    // รีเฟรชตารางให้แสดงผล
                    frm.refresh_field("meeting_participants_table");
                }

                // ล้างค่าช่องเลือก meeting_participants
                frm.set_value("meeting_participants", "");
            });
        }
    }
});

// ฟิลเตอร์ให้ meeting_participants ไม่แสดงชื่อที่มีใน meeting_participants_table แล้ว
frappe.ui.form.on("Minutes Of The Meeting", {
    refresh: function(frm) {
        frm.set_query("meeting_participants", function() {
            let selected_personnel = (frm.doc.meeting_participants_table || []).map(row => row.list_meeting_participants);
            return {
                filters: [["name", "not in", selected_personnel]]
            };
        });
    }
});

frappe.ui.form.on('Minutes Of The Meeting', {
    refresh: function(frm) {
        if (frm.doc.fullname) {
            fetch_job_positions(frm);
        }
    },

    fullname: function(frm) {
        if (frm.doc.fullname) {
            fetch_job_positions(frm);
        } else {
            frm.set_value('job_position', "");
        }
    }
});

function fetch_job_positions(frm) {
    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Personnel",
            filters: {
                fullname: frm.doc.fullname
            },
            fields: ["job_position", "job_position2"],
            limit_page_length: 100
        },
        callback: function(r) {
            if (r.message) {
                let job_position_options = [];
                
                r.message.forEach(d => {
                    if (d.job_position) job_position_options.push(d.job_position);
                    if (d.job_position2) job_position_options.push(d.job_position2);
                });

                job_position_options = [...new Set(job_position_options)]; // กำจัดค่าที่ซ้ำกัน

                frm.set_df_property('job_position', 'options', job_position_options.join('\n'));
                frm.refresh_field('job_position');
            }
        }
    });
}



//ดึงข้อมูลจาก HA Group มาแสดงในตาราง Minutes Of The Meeting Listname Table
frappe.ui.form.on("Minutes Of The Meeting", {
    team: function(frm) {
        if (cur_frm.doc.team) {
            frappe.model.with_doc("HA Group", cur_frm.doc.team, function() {
                var ha_group = frappe.model.get_doc("HA Group", cur_frm.doc.team);
                cur_frm.clear_table("minutes_meeting_listname_table");
                $.each(ha_group.ha_group_table, function(index, row) {
                    var d = cur_frm.add_child("minutes_meeting_listname_table");
                    d.fullname = row.fullname;
                    d.position = row.position;
                    d.duty = row.duty;
                });
                cur_frm.refresh_field("minutes_meeting_listname_table");

                // ซ่อนปุ่ม Add Row
                frm.fields_dict["minutes_meeting_listname_table"].grid.wrapper
                    .find(".grid-add-row, .grid-upload, .grid-download, .grid-add-multiple-rows").hide();
            });
        }
    }
});
